SELECT [T_Nota Fiscal].CODIGO, [T_Nota Fiscal].pc, [T_Nota Fiscal].codreq, [T_Nota Fiscal].codreq AS OC, [T_Nota Fiscal].numnf, [T_Nota Fiscal].valor, [Cadastro de Proposta].DataDeEntrada
FROM [T_Nota Fiscal] LEFT JOIN [Cadastro de Proposta] ON [T_Nota Fiscal].pc = [Cadastro de Proposta].PC
WHERE ((([Cadastro de Proposta].DataDeEntrada)>=#1/1/2015#));

SELECT tblInsumos.insumoDescricao, tblInsumos.insumoUnidade, tblInsumos.insumoTipo
FROM tblInsumos
WHERE (((tblInsumos.insumoTipo) Is Null));

SELECT [T_Nota Fiscal].codreq, [T_Nota Fiscal].numnf, [T_Nota Fiscal].valor
FROM [T_Nota Fiscal]
WHERE ((([T_Nota Fiscal].codreq)=21139014));
